/*
 * Tombstone service worker.
 *
 * This path used to serve a 47 KB Workbox 5.1.4 bundle generated by
 * next-offline. next-offline was removed from the build in 265984c, but that
 * commit only touched next.config.js — the generated worker stayed in public/
 * and kept being served with a 200. Nothing has registered it since, and
 * nothing ever unregistered it, so every browser that installed it while
 * next-offline was live still has it intercepting fetches and serving from an
 * "offlineCache" (maxEntries: 200) that will never be refreshed. Some of those
 * cached entries point at static/locales/, a directory that no longer exists.
 *
 * Deleting the file is not enough: a 404 on the worker script does not
 * reliably unregister an installed worker, and until the browser re-checks it,
 * the stale one keeps serving. So this replaces it with a worker whose only
 * job is to remove itself and its caches.
 *
 * next.config.js serves this with `Cache-Control: max-age=0, must-revalidate`
 * so browsers holding the old worker pick this one up promptly.
 *
 * Safe to delete once traffic has cycled — a release or two is plenty.
 */

self.addEventListener('install', () => {
	// Replace the old worker immediately rather than waiting for every tab it
	// controls to close.
	self.skipWaiting();
});

self.addEventListener('activate', event => {
	event.waitUntil(
		(async () => {
			// Drop everything the old worker cached, including offlineCache
			// entries pointing at paths that no longer exist.
			const keys = await caches.keys();
			await Promise.all(keys.map(key => caches.delete(key)));

			await self.registration.unregister();

			// Reload open windows so they leave uncontrolled instead of being
			// served by a worker on its way out.
			const clients = await self.clients.matchAll({ type: 'window' });
			clients.forEach(client => client.navigate(client.url));
		})()
	);
});

// Deliberately no fetch handler: with none registered, the browser goes
// straight to the network instead of through this worker.
